css:
#eims-invoice { font-family: 'Source Sans Pro', Arial, sans-serif; color: #212529; }
.row { display: flex; width: 100%; }
.row .left { flex: 1; }
.row .right { flex: 1; text-align: right; }
.info { margin: 6px 0; }
.col { flex: 1; padding: 4px; font-size: 12px; }
.items { width: 100%; border-collapse: collapse; font-size: 12px; }
.items th { background: #f8f9fa; padding: 4px; }
.items td { padding: 4px; }
.summary .totals table th { text-align: left; padding: 3px; font-size: 12px; }
.summary .totals table td { padding: 3px; text-align: right; font-size: 12px; }
.terms-title { background: #e9ecef; padding: 6px 0 !important; font-size: 13px; }
.thanks { font-weight: bold; }
.reg { font-size: 11px; }
.qr { margin-top: 6px; }
@media print {
	.print-heading, .page-head, .navbar, .sidebar-container { display: none !important; }
}
